insert into public.ce_course2_resources(id,data) values
('course2_module8_pdf','{"base64": "", "sha256": "5ef8e488a1855dcf8e6b4fbe7801c066e35a5065bd476b64d4205455906506b5", "filename": "CE_HALO_Course2_Module08_AFE_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course2_module8_questions','[{"module_id": "course_2_module_8", "question_id": "course_2_module_8_q01", "question_number": 1, "stem": "Which combination of findings should raise the strongest suspicion for AFE?", "choice_a": "Sudden peripartum hypoxia, hypotension or cardiac arrest, and early coagulopathy", "choice_b": "Uterine tenderness with fever alone", "choice_c": "Isolated postpartum hypertension without other symptoms", "choice_d": "Mild postpartum fatigue and normal vital signs", "correct_choice": "a", "rationale": "The classic AFE triad is acute hypoxia, hypotension or cardiac arrest, and coagulopathy occurring in the peripartum period.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q02", "question_number": 2, "stem": "AFE is best characterized as:", "choice_a": "A definitive laboratory diagnosis", "choice_b": "A clinical diagnosis of exclusion", "choice_c": "A histopathologic-only diagnosis", "choice_d": "A radiologic diagnosis", "correct_choice": "b", "rationale": "AFE is a clinical diagnosis of exclusion; no lab test or imaging can confirm it in real time.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q03", "question_number": 3, "stem": "The pathophysiologic cascade of AFE most commonly begins with:", "choice_a": "IgE-mediated anaphylaxis to fetal protein", "choice_b": "Direct viral injury to the alveolar epithelium", "choice_c": "A non-IgE anaphylactoid reaction with complement activation and mast cell degranulation after amniotic fluid components enter maternal circulation", "choice_d": "Acute bacterial endotoxemia", "correct_choice": "c", "rationale": "AFE is best described as a non-IgE anaphylactoid reaction with complement activation and cytokine surge, not classical IgE anaphylaxis.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q04", "question_number": 4, "stem": "Phase 1 of AFE is dominated by:", "choice_a": "Insidious onset over several days", "choice_b": "Chronic hypertension and proteinuria", "choice_c": "Isolated hemorrhage without cardiovascular changes", "choice_d": "Acute pulmonary vasoconstriction, RV strain or failure, hypoxemia, and cardiovascular collapse", "correct_choice": "d", "rationale": "Phase 1 features acute pulmonary hypertension, RV failure, hypoxemia, hypotension, and often cardiac arrest.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q05", "question_number": 5, "stem": "Phase 2 of AFE is dominated by:", "choice_a": "Hemostatic failure with DIC, LV dysfunction, pulmonary edema, and multiorgan hypoperfusion", "choice_b": "Isolated hypertension", "choice_c": "Chronic musculoskeletal pain", "choice_d": "Full recovery within minutes", "correct_choice": "a", "rationale": "Phase 2 features DIC, LV dysfunction, pulmonary edema, and multiorgan hypoperfusion in survivors of the initial collapse.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q06", "question_number": 6, "stem": "Because pregnancy elevates baseline fibrinogen, a fibrinogen level of 2 g/L during suspected AFE should be interpreted as:", "choice_a": "Reassuring evidence against DIC", "choice_b": "A late and dangerous sign of severe obstetric hemostatic failure requiring immediate replacement", "choice_c": "Normal for pregnancy", "choice_d": "An indication to withhold cryoprecipitate", "correct_choice": "b", "rationale": "Term parturients have fibrinogen typically 4–6 g/L. A value of 2 g/L reflects severe depletion and requires urgent fibrinogen replacement.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q07", "question_number": 7, "stem": "The extrinsic coagulation pathway is activated in AFE primarily by:", "choice_a": "Autoimmune antibody formation", "choice_b": "Viral RNA in maternal serum", "choice_c": "Tissue factor released from amniotic fluid components entering the maternal circulation", "choice_d": "Bacterial endotoxin", "correct_choice": "c", "rationale": "Amniotic fluid is rich in tissue factor, which activates the extrinsic pathway and drives rapid DIC.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q08", "question_number": 8, "stem": "The single most important initial CRNA action when AFE is suspected is to:", "choice_a": "Order a chest CT before treatment", "choice_b": "Complete registry paperwork before starting resuscitation", "choice_c": "Wait for confirmatory laboratory testing before intervening", "choice_d": "Announce suspected AFE, call for help, and activate the obstetric emergency response while beginning airway, breathing, and circulation support", "correct_choice": "d", "rationale": "Recognition, help, activation, and immediate ABC support are the priority; do not wait for confirmatory testing.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q09", "question_number": 9, "stem": "For a gravid patient with a fundus at or above the umbilicus who requires CPR, the correct pregnancy modification is:", "choice_a": "Continuous manual left uterine displacement with supine chest compressions", "choice_b": "Prone positioning", "choice_c": "Left lateral tilt at 30° during compressions", "choice_d": "Withholding defibrillation because of pregnancy", "correct_choice": "a", "rationale": "Current AHA guidance favors supine compressions with continuous manual left uterine displacement to relieve aortocaval compression.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q10", "question_number": 10, "stem": "Resuscitative hysterotomy (perimortem cesarean delivery) during maternal cardiac arrest primarily benefits:", "choice_a": "Neither the mother nor the neonate", "choice_b": "Both the mother and the neonate by improving venous return, reducing aortocaval compression, and increasing the likelihood of maternal ROSC", "choice_c": "The neonate only", "choice_d": "Only the mother", "correct_choice": "b", "rationale": "Uterine evacuation improves venous return and ventilation mechanics, benefiting maternal resuscitation as well as neonatal survival.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q11", "question_number": 11, "stem": "The vasopressor most likely to spare pulmonary vascular resistance and support the failing right ventricle in early AFE is:", "choice_a": "Nitroprusside", "choice_b": "Dopamine at renal-dose infusion", "choice_c": "Vasopressin", "choice_d": "Phenylephrine", "correct_choice": "c", "rationale": "Vasopressin increases systemic vascular resistance with relatively less pulmonary vasoconstriction, which is helpful in RV failure with pulmonary hypertension.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q12", "question_number": 12, "stem": "Excessive crystalloid administration during AFE resuscitation is problematic because it can:", "choice_a": "Improve fibrinogen levels", "choice_b": "Reverse DIC", "choice_c": "Cure pulmonary hypertension", "choice_d": "Worsen RV dilation, pulmonary edema, tissue edema, and dilutional coagulopathy", "correct_choice": "d", "rationale": "Excessive crystalloid worsens RV distension, edema, and dilutional coagulopathy; balanced blood products are preferred.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q13", "question_number": 13, "stem": "The uterotonic that should be avoided in patients with severe hypertension is:", "choice_a": "Methylergonovine", "choice_b": "Misoprostol", "choice_c": "Oxytocin", "choice_d": "Calcium gluconate", "correct_choice": "a", "rationale": "Methylergonovine can cause severe vasoconstriction and hypertension and is contraindicated in severe hypertension.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q14", "question_number": 14, "stem": "Rapid IV bolus of oxytocin should be avoided because it can cause:", "choice_a": "Severe hypertension", "choice_b": "Profound hypotension and tachycardia", "choice_c": "Bronchospasm", "choice_d": "Malignant hyperthermia", "correct_choice": "b", "rationale": "Rapid oxytocin bolus causes profound systemic vasodilation, hypotension, and reflex tachycardia; use dilute infusion or slow controlled bolus.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q15", "question_number": 15, "stem": "Which uterotonic should generally be avoided in patients with reactive airway disease?", "choice_a": "Oxytocin", "choice_b": "Misoprostol", "choice_c": "Carboprost (15-methyl PGF2α)", "choice_d": "Methylergonovine", "correct_choice": "c", "rationale": "Carboprost can cause bronchospasm and is generally avoided in reactive airway disease.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q16", "question_number": 16, "stem": "For selected refractory acute pulmonary hypertension and RV failure during AFE, an appropriate inhaled pulmonary vasodilator option is:", "choice_a": "Inhaled magnesium", "choice_b": "Inhaled nitroprusside", "choice_c": "Inhaled succinylcholine", "choice_d": "Inhaled nitric oxide or inhaled epoprostenol", "correct_choice": "d", "rationale": "Inhaled nitric oxide and inhaled epoprostenol are selective pulmonary vasodilators used in selected refractory pulmonary hypertension.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q17", "question_number": 17, "stem": "Which laboratory pattern is most consistent with AFE-associated DIC?", "choice_a": "Rapidly falling fibrinogen, thrombocytopenia, prolonged PT and aPTT, elevated D-dimer", "choice_b": "Elevated fibrinogen, normal PT/aPTT, normal D-dimer", "choice_c": "Isolated leukocytosis without coagulation changes", "choice_d": "Hyperkalemia without other findings", "correct_choice": "a", "rationale": "AFE-associated DIC produces falling fibrinogen, thrombocytopenia, prolonged PT/aPTT, and elevated D-dimer.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q18", "question_number": 18, "stem": "Viscoelastic testing during AFE resuscitation is most useful because it:", "choice_a": "Replaces the need for clinical assessment", "choice_b": "Guides targeted replacement of fibrinogen, platelets, and plasma based on real-time functional clot data", "choice_c": "Determines fetal viability", "choice_d": "Confirms the diagnosis of AFE", "correct_choice": "b", "rationale": "Viscoelastic testing does not diagnose AFE but guides targeted component therapy during massive transfusion.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q19", "question_number": 19, "stem": "Which condition most closely mimics AFE by producing sudden peripartum collapse and can coexist with it?", "choice_a": "Postpartum blues", "choice_b": "Isolated bladder distension", "choice_c": "Massive obstetric hemorrhage", "choice_d": "Peripartum lactation mastitis", "correct_choice": "c", "rationale": "Massive obstetric hemorrhage is a leading competing diagnosis and often coexists with AFE during the same crisis.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q20", "question_number": 20, "stem": "Which finding would most argue AGAINST high or total spinal anesthesia as the cause of peripartum collapse?", "choice_a": "Ascending motor weakness", "choice_b": "Hypotension and bradycardia after neuraxial dosing", "choice_c": "Difficulty speaking after epidural bolus", "choice_d": "Early diffuse coagulopathy with fibrinogen depletion and surgical field oozing", "correct_choice": "d", "rationale": "Early DIC and diffuse coagulopathy are not features of high spinal and should raise concern for AFE or another coagulopathic process.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q21", "question_number": 21, "stem": "Extracorporeal membrane oxygenation (ECMO) for AFE should typically be considered:", "choice_a": "Early, when severe hypoxemia, pulmonary hypertension, RV failure, or refractory shock persists despite optimized management, and an ECMO-capable team is available", "choice_b": "Never; it is contraindicated in AFE", "choice_c": "Only after all bleeding has permanently stopped", "choice_d": "Only if the diagnosis is confirmed by autopsy", "correct_choice": "a", "rationale": "Early VA-ECMO consultation is reasonable for refractory cardiopulmonary failure in AFE, with recognition of bleeding and anticoagulation challenges.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q22", "question_number": 22, "stem": "The safest way to manage AFE Registry specimen collection during active resuscitation is to:", "choice_a": "Ask the airway clinician to complete all registry tasks during intubation", "choice_b": "Delegate specimen preservation to a team member only after critical resuscitative actions are underway", "choice_c": "Pause resuscitation until specimens are collected", "choice_d": "Delay transfusion until research specimens are obtained", "correct_choice": "b", "rationale": "Clinical care always takes priority; registry activities are delegated and must not interrupt airway, CPR, transfusion, or hemorrhage control.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q23", "question_number": 23, "stem": "The 2024 Society for Maternal-Fetal Medicine clinical guideline on AFE emphasizes all of the following EXCEPT:", "choice_a": "Multidisciplinary team activation and early aggressive resuscitation", "choice_b": "Clinical diagnosis of exclusion", "choice_c": "Delaying massive transfusion until a specific laboratory threshold is reached", "choice_d": "High-quality CPR and ACLS with pregnancy modifications", "correct_choice": "c", "rationale": "SMFM 2024 emphasizes early aggressive resuscitation and early massive transfusion when bleeding, shock, or coagulopathy is present — not delay for a lab threshold.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q24", "question_number": 24, "stem": "Stafford et al. (2020) analysis of the U.S. AFE International Registry reported that:", "choice_a": "AFE occurs only after cesarean delivery", "choice_b": "AFE is prevented by routine antenatal aspirin", "choice_c": "AFE was found to have no consistent clinical pattern", "choice_d": "AFE cases show recognizable patterns of acute cardiorespiratory compromise and coagulopathy, and registry data help refine diagnostic criteria and management", "correct_choice": "d", "rationale": "Registry analyses have helped clarify the clinical syndrome and support refinement of diagnostic and management approaches.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_8", "question_id": "course_2_module_8_q25", "question_number": 25, "stem": "Collins et al. (2017) OBS2 trial supported which of the following principles relevant to AFE-associated coagulopathy?", "choice_a": "Viscoelastometric-guided fibrinogen concentrate replacement can be applied to postpartum hemorrhage management", "choice_b": "Fibrinogen replacement is unnecessary in obstetric hemorrhage", "choice_c": "Cryoprecipitate should never be used in pregnancy", "choice_d": "Universal empiric factor VIIa is safe in obstetric hemorrhage", "correct_choice": "a", "rationale": "The OBS2 trial supported viscoelastometric-guided fibrinogen replacement strategies applicable to obstetric hemorrhage and coagulopathy such as that seen in AFE.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
